arguments.content:
// stair_tracker.js

let totalSteps = 0;

function addSet() {
  totalSteps += 1;
  updateDisplay();
}

function updateDisplay() {
  const displayElement = document.getElementById('total-steps-display');
  if (displayElement) {
    displayElement.textContent = 'Total Steps: ' + totalSteps;
  }
}

// Add event listener for the button click
const addButton = document.getElementById('add-set-button');
if (addButton) {
  addButton.addEventListener('click', addSet);
}

